<template>
  <div>
    <b-row>
      <b-col lg="12">
        <b-row>
          <b-col>
            <b-alert show variant="danger" v-if="messageAlert" dismissible>{{
              messageAlert
            }}</b-alert>
          </b-col>
        </b-row>
        <b-row>
          <b-col cols="11"
            ><b>Entidades cadastradas: {{ companies.length }}</b></b-col
          >
          <b-col>
            <b-button
              size="sm"
              block
              variant="secondary"
              :disabled="isLoading"
              @click="refreshCompanies()"
            >
              <b-icon icon="arrow-clockwise"></b-icon
            ></b-button>
          </b-col>
        </b-row>
        <b-overlay :show="isLoading" rounded="sm">
          <p class="text-danger" v-if="companies.length == 0">
            Sem nenhuma Entidade cadastrada até o momento.
          </p>
          <table v-else class="table table-sm table-hover table-stripped">
            <thead>
              <tr style="font-size: 9pt" class="bg-secondary text-white">
                <th>Nome da entidade</th>
                <th>Telemóvel</th>
                <th>E-mail</th>
                <th>Website</th>
                <th>Data de cadastro</th>
                <th>Status</th>
                <th>Configs</th>
              </tr>
            </thead>
            <tbody>
              <tr
                v-for="company in companies"
                :key="company.id"
                style="font-size: 9pt; cursor: pointer"
                :class="{ 'text-danger': company.companyStatus === 0 }"
              >
                <td>{{ company.companyName }}</td>
                <td>{{ company.companyPhone }}</td>
                <td>{{ company.companyEmail }}</td>
                <td>{{ company.companyWebsite }}</td>
                <td v-date-format="company.createdAt"></td>
                <td
                  @click="updateCompany(company)"
                  :class="{
                    'text-success': company.companyStatus === 0,
                    'text-danger': company.companyStatus === 1,
                  }"
                >
                  {{ convertStatus(company.companyStatus) }}
                </td>
                <td>
                  <b-row>
                    <b-col
                      class="text-center"
                      @click="addUser(company)"
                      style="font-size: 12pt"
                      ><b-icon
                        icon="person-plus-fill"
                        variant="primary"
                      ></b-icon
                    ></b-col>
                  </b-row>
                </td>
              </tr>
            </tbody>
          </table>
        </b-overlay>
      </b-col>
    </b-row>
    <b-modal hide-footer ref="company-add-new-user" title="Novo usuário">
      <AddUserComponent />
    </b-modal>
    <b-modal hide-footer ref="deactivate-company" title="Deletar">
      <p class="text-danger text-center">
        {{ alertDetails }}
      </p>
      <b-row>
        <b-col>
          <b-button block size="sm" @click="cancelDeactivation()"
            >Cancelar</b-button
          >
        </b-col>
        <b-col>
          <b-button
            block
            size="sm"
            variant="danger"
            @click="decidedToDeActivate()"
            >SIM</b-button
          >
        </b-col>
      </b-row>
    </b-modal>
  </div>
</template>

<script>
import axios from "axios";
import { mapGetters } from "vuex";
import logs from "@/utils/logs";
import AddUserComponent from "@/components/company/AddNewUser.vue";

export default {
  name: "CompanyComponent",

  components: {
    AddUserComponent,
  },

  data: () => ({
    checked: true,
    notChecked: false,
    companyDeactivationId: 0,
    selectedcompany: {},
    userUpdationId: 0,
    alertDetails: "",
    messageAlert: "",

    currentCompany: {},
  }),

  computed: {
    ...mapGetters(["isLoading", "user", "token", "companies", "users"]),
  },

  created() {
    this.refreshCompanies();
  },

  methods: {
    addUser(company) {
      if (company.id == 2) {
        this.messageAlert =
          "Não está autorizado a adicionar usuários a esta entidade.";
        return;
      }
      this.$store.commit("SET_CURRENT_COMPANY", company);
      this.$refs["company-add-new-user"].show();
    },

    refreshCompanies() {
      this.$store.dispatch("getAllCompanies");
    },

    updateUser(user) {
      this.userUpdationId = user.id;
      this.form = {
        name: user.name,
        phone: user.phone,
        email: user.email,
        userRole: user.userRole,
        status: user.status,
        companyId: user.companyId,
      };
    },

    decidedToDeActivate() {
      this.$store.commit("LOADING_STATUS", true);
      axios
        .put(`/api/company/${this.companyDeactivationId}`, {
          companyStatus: this.updationStatus,
        })
        .then((res) => {
          const data = res.data;
          if (data.success == true) {
            this.showToast("Sucesso!", "success", data.message);
            const status =
              this.updationStatus == 0 ? "activada" : "desactivada";
            const logsParams = logs(
              this.user,
              `${this.selectedcompany.companyName} com ${this.companyDeactivationId} foi ${status} com sucesso.`,
              "Status da operadora"
            );
            this.$store.dispatch("addLog", logsParams);
            this.refreshCompanies();
          } else {
            this.showToast("Erro!", "warning", data.message);
          }
          this.cancelDeactivation();
          this.$store.commit("LOADING_STATUS", false);
        })
        .catch((err) => {
          this.cancelDeactivation();
          this.$store.commit("LOADING_STATUS", false);
          this.showToast("Erro!", "danger", err.message);
        });
    },

    updateCompany(company) {
      if (company.id == 2) {
        this.messageAlert =
          "Não está autorizado a desactivar esta entidade.";
        return;
      }
      this.companyDeactivationId = company.id;
      this.selectedcompany = company;
      this.alertDetails =
        company.companyStatus == 1
          ? "Deseja realmente desactivar esta Operadora?"
          : "Deseja realmente activar esta Operadora?";
      this.updationStatus = company.companyStatus == 1 ? 0 : 1;
      this.$refs["deactivate-company"].show();
    },

    cancelDeactivation() {
      this.companyDeactivationId = 0;
      this.$refs["deactivate-company"].hide();
    },

    showToast(title, variant, msg) {
      this.$bvToast.toast(`${msg}`, {
        title,
        variant,
        solid: true,
        toaster: "b-toaster-top-center",
        autoHideDelay: 5000,
      });
    },

    convertRole(role) {
      if (role == 1) {
        return "Admin";
      } else if (role == 2) {
        return "Atendimento";
      } else if (role == 3) {
        return "Analista de crédito";
      }
    },

    convertStatus(status) {
      if (status === 1) {
        return "Desactivar";
      } else if (status === 0) {
        return "Activar";
      }
    },

    resetFields() {
      this.userUpdationId = 0;
      this.form = {
        name: "",
        phone: "258",
        email: "",
        password: Math.floor(Math.random() * 1000000) + 1,
        userRole: 2,
        status: 1,
        companyId: 1,
      };
    },
  },
};
</script>
