<template>
  <div>
    <CompanyNavBar />
    <div class="card">
      <div class="card-body text-secondary">
        <b-row>
          <b-col lg="2" md="4" sm="12">
            <b-row>
              <b-col
                lg="12"
                md="12"
                sm="12"
                style="cursor: pointer; border-bottom: 1px solid black"
                class="mt-0"
                @click="selectPanel(1)"
                ><b-icon icon="bank2"></b-icon> &nbsp;&nbsp;&nbsp;<b
                  >Operadores</b
                ></b-col
              >
              <b-col
                lg="12"
                md="12"
                sm="12"
                style="cursor: pointer; border-bottom: 1px solid black"
                class="mt-0"
                @click="selectPanel(2)"
                ><b-icon icon="plus-lg"></b-icon> &nbsp;&nbsp;&nbsp;<b
                  >Novo Operador</b
                ></b-col
              >
              <b-col
                lg="12"
                md="12"
                sm="12"
                style="cursor: pointer; border-bottom: 1px solid black"
                class="mt-0"
                @click="selectPanel(3)"
                ><b-icon icon="people-fill"></b-icon> &nbsp;&nbsp;&nbsp;<b
                  >Usuários</b
                ></b-col
              >
            </b-row>
          </b-col>
          <b-col lg="10" md="8" sm="12">
            <CompanyDetailsComponent v-if="selectedPanel === 1" />
            <AddNewCompanyComponent
              v-if="selectedPanel === 2"
              v-on:update-parent="selectPanel(2)"
            />
            <SuperAdminComponent v-if="selectedPanel === 3" />
          </b-col>
        </b-row>
      </div>
    </div>
  </div>
</template>

<script>
import { mapGetters } from "vuex";

import CompanyDetailsComponent from "@/components/company/CompanyComponent.vue";
import AddNewCompanyComponent from "@/components/company/AddNewCompanyComponent.vue";
import SuperAdminComponent from "@/components/company/SuperAdminComponent.vue";
import CompanyNavBar from "@/components/CompanyNavBar.vue";

export default {
  data: () => ({
    selectedPanel: 1,
  }),

  components: {
    CompanyDetailsComponent,
    AddNewCompanyComponent,
    SuperAdminComponent,
    CompanyNavBar,
  },

  computed: {
    ...mapGetters([
      "isLoading",
      "user",
      "token",
      "company",
      "provinces",
      "districts",
    ]),
  },

  created() {
    setTimeout(() => {
      this.getProvinces();
    }, 1000);
  },

  methods: {
    getProvinces() {
      this.$store.dispatch("getProvinces");
    },

    selectPanel(panel) {
      if (panel === 1) {
        this.selectedPanel = 1;
      } else if (panel === 2) {
        this.selectedPanel = 2;
      } else if (panel === 3) {
        this.selectedPanel = 3;
      }
    },
  },
};
</script>

<style scoped>
.card {
  width: 100%;
}
.table {
  font-size: 14px;
}

th {
  font-size: 10px;
  font-weight: bold;
}
</style>
